SELECT N.DESCRPROD AS PRODUTO, SUM(CASE WHEN N.ATUALESTOQUE = 1 THEN (N.VLRUNIT * N.QTDNEG) WHEN N.ATUALESTOQUE = -1 THEN -(N.VLRUNIT * N.QTDNEG) ELSE 0 END) AS VALOR_TOTAL, SUM(CASE WHEN N.ATUALESTOQUE = 1 THEN N.PESO_ITEM WHEN N.ATUALESTOQUE = -1 THEN -N.PESO_ITEM ELSE 0 END) AS PESO_TOTAL, ROUND((SUM(CASE WHEN N.ATUALESTOQUE = 1 THEN N.PESO_ITEM WHEN N.ATUALESTOQUE = -1 THEN -N.PESO_ITEM ELSE 0 END) / NULLIF((SELECT SUM(CASE WHEN ATUALESTOQUE = 1 THEN PESO_ITEM WHEN ATUALESTOQUE = -1 THEN -N.PESO_ITEM ELSE 0 END) FROM IMP_NOTAS_ARMAZ WHERE CODPARC = :VAR_PARCEIRO_SELECIONADO), 0)) * 100, 2) AS PERC_PESO FROM IMP_NOTAS_ARMAZ N WHERE N.CODPARC = :VAR_PARCEIRO_SELECIONADO GROUP BY N.DESCRPROD HAVING SUM(CASE WHEN N.ATUALESTOQUE = 1 THEN N.PESO_ITEM WHEN N.ATUALESTOQUE = -1 THEN -N.PESO_ITEM ELSE 0 END) > 0.01 ORDER BY PESO_TOTAL DESC